type Row = { id: string; label: string };
type ReconcileResult = { rows: Row[]; reused: number };

function reconcileRows(current: Row[], next: Row[]): ReconcileResult {
  const existing = new Map(current.map((row) => [row.id, row]));
  let reused = 0;
  const rows = next.map((row) => {
    const previous = existing.get(row.id);
    if (previous === undefined) {
      return row;
    }
    reused += 1;
    return { ...previous, ...row };
  });
  return { rows, reused };
}
